    "factor_updates": [
      {
        "factor": "Early 2026 death toll pace on Central Mediterranean route",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "There is 606 deaths by late February; if the pace continues through March–April, crossing 1,000 by May is plausible."
      },
      {
        "factor": "Seasonal spring conditions increasing crossings",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Spring typically brings more crossings, which could increase fatalities if rescue capacity remains stressed."
      },
      {
        "factor": "Historical baselines and annual tolls",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Recent years have seen high tolls; 1,000 by May is within reach given current dynamics."
      },
      {
        "factor": "Uncertainty in SAR capacity and policy changes",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Policy changes could alter outcomes in either direction; effect on near-term count is uncertain."
      }
    ],
    "synthesis_rationale": "The posterior probability is driven by a strong upward push from multiple factors, starting from a solid anchor near 0.75 and updating with strong (pace), moderate (seasonality, baselines) and weak-neutral factors (SAR uncertainty). Calibration toward 0.98 reflects the aggregation of correlated updates and the high degree of confidence in near-term risk, while acknowledging that data lags and policy shifts could tilt outcomes."
  }
}

