{
  "probability": 0.60,
  "range_low": 0.50,
  "range_high": 0.70,
  "summary": [
    "Early-2026 toll (~606 dead/missing by February) suggests the pace is close to the 1,000 threshold for May if the trend continues.",
    "March–April would need roughly 394 additional deaths; given high recent baselines, this remains plausible but uncertain.",
    "Uncertainty factors like data reporting lags and SAR/policy dynamics could dampen or amplify fatalities, introducing downside and upside risks.",
    "Overall, a calibrated posterior around 60% with a plausible 50–70% range reflects both the high pace and substantial near-term uncertainty."
  ],
  "confidence": "medium",
  "narrative": "The February–April trajectory shows a historically high pace that could reach 1,000 deaths by May, but data lags and possible SAR/policy shifts inject substantial uncertainty. A centered probability near 60% with a 50–70% range captures the balance between the strong early signal and the many risk factors.",
  "justification": {
    "anchor": {
      "probability": 0.75,
      "basis": "Reference class is annual Mediterranean migrant-death toll (IOM Missing Migrants Project). Early-2026 counts (about 606 by late February) imply a plausible path to 1,000 by May, supporting a high prior around 0.75."
    },
    "factor_updates": [
      {
        "factor": "March–April 2026 death pace (Central Mediterranean)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths through February suggest a pace that, if sustained, would reach or exceed 1,000 by May, increasing the probability."
      },
      {
        "factor": "Weather and seas conditions",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Spring weather and rough seas typically raise crossing activity and fatalities."
      },
      {
        "factor": "Policy/SAR capacity and enforcement",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "If SAR capacity improves or policy changes facilitate rescue, fatalities could be reduced, lowering the probability."
      },
      {
        "factor": "Data uncertainty and reporting lags",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Incomplete reporting can understate near-term totals, making the exact attainment of 1,000 by May less certain."
      },
      {
        "factor": "Baseline high annual totals in 2024–2025",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Historically high tolls raise the odds of crossing 1,000 in the early months of 2026."
      }
    ],
    "synthesis_rationale": "The anchor starts at a high prior (0.75) based on a reference class of yearly Mediterranean death tolls. Upward updates from pace, weather, and baselines are tempered by downward updates from potential SAR improvements and data uncertainty. The net integration yields a calibrated probability near 0.60, with a 0.50–0.70 range to reflect substantial near-term uncertainty and potential reporting issues."
  }
}
